def ref(path,raw):return {'path':str(path),'bytes':len(raw),'sha256':m.digest(raw)}


class DriverTests(unittest.TestCase):
    def setUp(self):
        self.tmp=tempfile.TemporaryDirectory();self.root=Path(self.tmp.name).resolve()
        self.disk=patch.object(m.shutil,'disk_usage',return_value=type('D',(),{'free':10**12})())
        self.disk.start()
        self.prior_raw,self.prior_policy=self.failure_fixture()
        prior=patch.object(m,'FAILED_THIRD',self.prior_policy);prior.start();self.addCleanup(prior.stop)
    def tearDown(self):self.disk.stop();self.tmp.cleanup()


    def failure_fixture(self):
        """Synthetic historical package; no host observation or external fixture."""
        boot='00000000-0000-4000-8000-000000000001'
        admission=m.encode({'schema_version':'polymarket_native_source_profile_admission_v3',
            'operator_source_head':m.FAILED_THIRD_OPERATOR_HEAD,'boot_id':boot}).decode()
        qa=m.encode({'source_commit':m.FAILED_THIRD_OPERATOR_HEAD}).decode()
        closure=m.encode({'source_commit':m.FAILED_THIRD_OPERATOR_HEAD}).decode()
        process=m.encode({'schema_version':'polymarket_native_source_profile_process_v2',
            'admission_sha256':m.digest(admission.encode()),'boot_id':boot,
            'footer_bytes_read':0,'trade_payload_bytes_read':0,'provider_requests':0}).decode()
        error=m.encode({'error_code':'native_profile_nested_header_ledger_schema',
            'status':'native_footer_profile_withheld'}).decode()
        rows=[{'event':'root_footer_v3_actual_preflight'},
              {'event':'root_footer_v3_actual_preflight_exit'},
              {'event':'root_footer_v3_prospective_admission','admission_utf8':admission,
               'qa_utf8':qa,'closure_utf8':closure},
              {'event':'root_footer_v3_producer_stdout','raw_UTF8':process},
              {'event':'root_footer_v3_producer_stdout','raw_UTF8':error},
              {'event':'root_footer_v3_actual_exit','exit_code':2,
               'stdout_bytes':len((process+error).encode()),'stdout_sha256':m.digest((process+error).encode())}]
        raw=''.join(m.encode(row).decode() for row in rows)
        policy={'bytes':len(raw.encode()),'sha256':m.digest(raw.encode())}
        for role,text in [('admission_utf8',admission),('qa_utf8',qa),
                          ('closure_utf8',closure),('process_utf8',process)]:
            policy[role]=(len(text.encode()),m.digest(text.encode()))
        return raw,policy

