        policy[schema]=(original_policy[0],len(raw),m.digest(raw),*original_policy[3:])
        with patch.object(m,'HISTORICAL_LEDGER_PINS',policy):
            return m.historical_header_ledger(ref(m.OP/original_policy[0],raw),raw)

